 * Finds all overlapping matches of a pattern within a string
 * @param {string} var0 - The string to search within
 * @param {string|RegExp} pattern0 - The pattern to search for
 * @returns {Array<{match: string, index: number}>} Array of all overlapping matches with their positions
 */
function findOverlappingMatches(var0, pattern0) {
  // Convert string pattern to RegExp if needed
  const regex = typeof pattern0 === 'string' 
    ? new RegExp(pattern0.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g')
    : new RegExp(pattern0.source, 'g');

  const matches = [];

  // Use String.prototype.matchAll (ES2020, stable in 2025+)
  // For overlapping matches, we need to manually iterate
  const patternStr = typeof pattern0 === 'string' ? pattern0 : pattern0.source;

  for (let i = 0; i <= var0.length - patternStr.length; i++) {
    const substring = var0.substring(i, i + patternStr.length);

    if (typeof pattern0 === 'string') {
      if (substring === pattern0) {
        matches.push({
          match: substring,
          index: i
        });
