import Decimal from 'decimal.js';

/**
 * Computes the Euclidean distance between two points
 * @param {number[] | Decimal[]} var0 - First point coordinates
 * @param {number[] | Decimal[]} var1 - Second point coordinates
 * @returns {Decimal} The Euclidean distance between the two points
 * @throws {Error} If points have different dimensions or are empty
 */
function euclideanDistance(var0, var1) {
  if (var0.length !== var1.length) {
    throw new Error('Points must have the same number of coordinates');
  }

  if (var0.length === 0) {
    throw new Error('Points cannot be empty');
  }

