 * @param {string} var0 - The column name to search in
 * @param {*} var1 - The value to match
 * @returns {number} The row index of the first matching entry, or -1 if not found
 */
async function findRowIndex(df0, var0, var1) {
  // Initialize DuckDB
  const db = new duckdb.Database();
  const connection = await db.connect();

  try {
    // Register the dataset as a relation in DuckDB
    await connection.registerTable('df0_table', df0);

