    const result = await connection.query(`
      SELECT row_number() OVER (ORDER BY rowid) - 1 as row_index
      FROM df0_table
      WHERE "${var0}" = ?
      LIMIT 1
    `, [var1]);

    // Extract the row index from the result
    const batches = result.toArray();

    if (batches.length === 0) {
