    .map(id => itemMap.get(id))
    .filter(item => item !== undefined);

  // Include items not in the sequence at the end (optional behavior)
  const usedIds = new Set(sequence);
  const unmappedItems = items.filter(item => !usedIds.has(item[idKey]));

  return [...reordered, ...unmappedItems];
}

