# One-Hot Encoding with Polars (2025+)

```javascript
import * as pl from "polars";

/**
 * Converts all categorical columns in a Polars DataFrame into multiple 
 * binary integer columns using one-hot encoding.
 * 
 * @param {pl.DataFrame} df0 - Input DataFrame
 * @returns {pl.DataFrame} - DataFrame with categorical columns one-hot encoded
 */
function oneHotEncodeCategories(df0) {
  let result = df0;

  // Get all column names and their data types
  const columnNames = result.columns;
  const schema = result.schema;

  // Iterate through each column
  for (const colName of columnNames) {
    const dtype = schema[colName];

    // Check if column is String type (categorical/discrete labels)
    if (dtype === pl.String || dtype.toString().includes("String")) {
      // Apply one-hot encoding to this column
      const oneHotDf = result.select(colName).toFrame().with_columns(
        pl
          .col(colName)
          .str.to_categorical()
          .to_dummies({ separator: "_" })
          .cast(pl.UInt8)
      );

      // Get the one-hot encoded columns (exclude original)
      const oneHotCols = oneHotDf
        .columns.filter((c) => c !== colName)
        .map((c) => pl.col(c).alias(`${colName}_${c}`));

      // Drop original column and add one-hot encoded columns
      result = result.drop(colName).hstack(
        oneHotDf.select(
          pl
            .col(colName)
            .str.to_categorical()
            .to_dummies({ separator: "_" })
            .cast(pl.UInt8)
        )
      );
    }
  }

  return result;
}

// Example usage:
const df0 = pl.DataFrame({
  age: [25, 30, 35],
  color: ["red", "blue", "red"],
  size: ["small", "large", "medium"],
  score: [95.5, 87.3, 92.1],
});

console.log("Original DataFrame:");
