 * @param {number} startValue - Starting value for numeric iteration
 * @param {number} limit - Upper limit (exclusive) for numeric iteration
 * @returns {Object<string, number[]>} Mapping of keys to arrays of numbers
 */
function generateKeyValueMapping(keys, startValue, limit) {
  // Validate inputs
  if (!Array.isArray(keys) || keys.length === 0) {
