/**
 * Sorts text elements with selective descending order for specified positions
 * @param {string[]} texts - Array of text elements to sort
 * @param {number[]} [descendingPositions] - Optional positions to sort in descending order
 * @returns {string[]} - Sorted array
 */
function selectiveSortTexts(texts, descendingPositions = []) {
  // Create array with original values and indices
  const indexed = texts.map((text, index) => ({ text, index }));

  // Partition into ascending and descending groups
  const descPos = new Set(descendingPositions);

  const ascending = indexed.filter(item => !descPos.has(item.index));
  const descending = indexed.filter(item => descPos.has(item.index));

  // Sort each group
  const sortedAscending = _.orderBy(ascending, ['text'], ['asc']);
  const sortedDescending = _.orderBy(descending, ['text'], ['desc']);

  // Merge back maintaining position constraints
  const result = new Array(texts.length);
  let ascIdx = 0, descIdx = 0;

  for (let i = 0; i < texts.length; i++) {
    if (descPos.has(i)) {
      result[i] = sortedDescending[descIdx++].text;
    } else {
      result[i] = sortedAscending[ascIdx++].text;
    }
  }

  return result;
}

