# Vector-Matrix Multiplication in JavaScript

```javascript
/**
 * Multiplies a numerical vector by a numerical matrix
 * Vector (1D array) × Matrix (2D array) = Result vector (1D array)
 * 
 * @param {number[]} vector - A 1D array representing the vector
 * @param {number[][]} matrix - A 2D array representing the matrix
 * @returns {number[]} - The resulting vector from the multiplication
 * @throws {Error} - If dimensions are incompatible
 */
function multiplyVectorByMatrix(vector, matrix) {
  // Input validation
  if (!Array.isArray(vector) || !Array.isArray(matrix)) {
    throw new Error("Vector and matrix must be arrays");
  }

  if (matrix.length === 0) {
    throw new Error("Matrix cannot be empty");
  }

  const vectorLength = vector.length;
  const matrixRows = matrix.length;
  const matrixCols = matrix[0].length;

  // Check dimension compatibility: vector length must equal matrix rows
  if (vectorLength !== matrixRows) {
    throw new Error(
      `Incompatible dimensions: vector length (${vectorLength}) must equal matrix rows (${matrixRows})`
    );
  }

  // Validate that all matrix rows have the same length
  for (let i = 0; i < matrix.length; i++) {
    if (!Array.isArray(matrix[i]) || matrix[i].length !== matrixCols) {
      throw new Error(`Matrix row ${i} has incorrect dimensions`);
    }
  }

  // Perform vector-matrix multiplication
  // Result vector length = number of matrix columns
  const result = new Array(matrixCols).fill(0);

  for (let col = 0; col < matrixCols; col++) {
    for (let row = 0; row < matrixRows; row++) {
      result[col] += vector[row] * matrix[row][col];
    }
  }

  return result;
}

// ===== EXAMPLES =====

// Example 1: Basic 2D case
const var0 = [2, 3, 4];
const var1 = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];
