console.log("Matrix:", var1);
console.log("Result:", multiplyVectorByMatrix(var0, var1));
// Expected: [2*1 + 3*4 + 4*7, 2*2 + 3*5 + 4*8, 2*3 + 3*6 + 4*9] = [42, 51, 60]

// Example 2: Non-square matrix
