console.log("Matrix:", matrix2);
console.log("Result:", multiplyVectorByMatrix(vector2, matrix2));
// Expected: [1*1 + 2*5, 1*2 + 2*6, 1*3 + 2*7, 1*4 + 2*8] = [11, 14, 17, 20]

// Example 3: Single element
