console.log("Vector:", vector3);
console.log("Matrix:", matrix3);
console.log("Result:", multiplyVectorByMatrix(vector3, matrix3));
// Expected: [5*2, 5*3, 5*4] = [10, 15, 20]

// Example 4: Error handling
