const columnIndices = [1, 3];

const result = computeIndexedMeans(testData, rowIndices, columnIndices);
console.log('Row Means:', result.rowMeans);      // [2.5, 10.5]
console.log('Column Means:', result.columnMeans); // [8.5, 10.5]
console.log('Summary:', result.summary);
```

