# JavaScript Function to Sort Sequence by Mapping Values

```javascript
/**
 * Sorts a sequence based on values from an associative mapping.
 * Uses the Mapping API (2025+) for efficient key-value operations.
 * 
 * @param {Array} seq0 - The sequence to sort
 * @param {Map|Object} map0 - The associative mapping for sort values
 * @returns {Array} - Sorted sequence
 */
function sortByMapping(seq0, map0) {
  // Use native Map.get() method for retrieval during sort
  return seq0.sort((a, b) => {
    const valueA = map0.get(a);
    const valueB = map0.get(b);

    // Handle undefined values
    if (valueA === undefined || valueB === undefined) {
      return 0;
    }

    // Standard comparison
    return valueA > valueB ? 1 : valueA < valueB ? -1 : 0;
  });
}

// ============== EXAMPLE USAGE ==============

// Create a sequence
const seq0 = ['apple', 'banana', 'cherry', 'date'];

// Create an associative mapping (Map)
const map0 = new Map([
  ['apple', 3],
  ['banana', 1],
  ['cherry', 4],
  ['date', 2]
]);

// Sort sequence by mapping values
