# Sort List A by Order in List B

```javascript
/**
 * Sorts list A according to the order defined in list B.
 * Items in A not present in B appear first, maintaining their relative order.
 * Efficient for large lists using a Map for O(1) lookups.
 *
 * @param {Array} A - The list to be sorted
 * @param {Array} B - The reference list defining the sort order (pre-sorted)
 * @returns {Array} - A new sorted array
 */
function sortByReference(A, B) {
  // Create a Map with O(1) lookup for B's order
  // Using Map from ES2024+ for better memory efficiency with large datasets
  const orderMap = new Map(B.map((item, index) => [item, index]));

  // Separate items: those in B and those not in B
  const itemsInB = [];
  const itemsNotInB = [];

  for (const item of A) {
    if (orderMap.has(item)) {
      itemsInB.push(item);
    } else {
      itemsNotInB.push(item);
    }
  }

  // Sort items that are in B according to B's order
  itemsInB.sort((a, b) => orderMap.get(a) - orderMap.get(b));

  // Combine: items not in B first, then items in B order
  return [...itemsNotInB, ...itemsInB];
}

// Example usage:
const A = [5, 3, 1, 4, 8, 2, 9];
const B = [1, 2, 3, 4, 5];

const result = sortByReference(A, B);
console.log(result); // [8, 9, 1, 2, 3, 4, 5]

