const fruitOrder = ['apple', 'banana', 'cherry', 'date'];

const sortedFruits = sortByReference(fruits, fruitOrder);
console.log(sortedFruits); // ['grape', 'elderberry', 'apple', 'banana', 'cherry', 'date']

// Example with large lists:
