const largeB = Array.from({ length: 5000 }, (_, i) => i * 10).sort(() => Math.random() - 0.5).sort((a, b) => a - b);

const startTime = performance.now();
const resultLarge = sortByReference(largeA, largeB);
const endTime = performance.now();

console.log(`Sorted ${largeA.length} items in ${(endTime - startTime).toFixed(2)}ms`);
```

