```javascript
import Table from 'cli-table3';

/**
 * Converts multiple lists into a two-dimensional table with custom column headers
 * @param {Array<Array>} dataLists - Array of arrays containing row data
 * @param {Array<string>} headers - Array of column header names
 * @returns {string} Formatted table string
 * @throws {Error} If headers length doesn't match data row lengths
 */
function convertListsToTable(dataLists, headers) {
  // Validate inputs
  if (!Array.isArray(dataLists) || dataLists.length === 0) {
    throw new Error('dataLists must be a non-empty array');
  }

  if (!Array.isArray(headers) || headers.length === 0) {
    throw new Error('headers must be a non-empty array');
  }

  // Validate that all rows have correct length
  for (let i = 0; i < dataLists.length; i++) {
    if (!Array.isArray(dataLists[i])) {
      throw new Error(`Row ${i} is not an array`);
    }
    if (dataLists[i].length !== headers.length) {
      throw new Error(
        `Row ${i} has ${dataLists[i].length} columns but ${headers.length} headers provided`
      );
    }
  }

  // Create table instance with cli-table3
  const table = new Table({
    head: headers.map(h => h.toString()),
    style: {
      head: [],
      border: ['cyan'],
      compact: false
    },
    wordWrap: true,
    colWidths: Array(headers.length).fill(20)
  });

  // Add rows to table
  dataLists.forEach(row => {
    table.push(row.map(cell => (cell === null || cell === undefined ? '' : cell.toString())));
  });

  return table.toString();
}

