        width: 0,
        // Disable rendering to avoid UI overhead
        render: false,
        // Use a unique ID to avoid conflicts
        id: 'missing-values-analyzer-' + Date.now()
    });

    // Helper function to check if a value is missing
    const isMissing = (value) => {
        if (value === null && includeNull) return true;
        if (value === undefined && includeUndefined) return true;
        if (strict && value === '') return true;
        return value === null || value === undefined || (strict && value === '');
    };

    // Analyze each column
