 * @param {*} var0 - The lower bound key (inclusive)
 * @param {*} var1 - The upper bound key (inclusive)
 * @returns {Map} A new Map containing entries within the range
 */
function getRangeEntries(dict0, var0, var1) {
  // Ensure var0 is the smaller value
  const [minKey, maxKey] = var0 <= var1 ? [var0, var1] : [var1, var0];

  const resultMap = new Map();

  // Iterate through the Map and collect entries within range
  for (const [key, value] of dict0) {
    if (key >= minKey && key <= maxKey) {
      resultMap.set(key, value);
    }
