        ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 as index,
        var0,
        var1,
        CASE 
          WHEN var0 = var1 THEN 'equal'
          WHEN var0 > var1 THEN 'greater'
          WHEN var0 < var1 THEN 'less'
