  const iterators = lists.map(list => list[Symbol.iterator]());

  // Track current position in each iterator
  const positions = new Array(lists.length).fill(0);

  // Generate values following the sequence
  const generator = function*() {
    for (const listIndex of sequence) {
      // Validate list index
      if (listIndex < 0 || listIndex >= lists.length) {
        throw new Error(`Invalid sequence index ${listIndex}. Must be between 0 and ${lists.length - 1}`);
      }

      // Get next value from specified list
      const { value, done } = iterators[listIndex].next();

      if (done) {
        throw new Error(`List at index ${listIndex} exhausted before sequence completed`);
      }

      yield value;
      positions[listIndex]++;
    }
  };

  // Use iter-ops pipe to consume and collect results
  return pipe(
    generator(),
    consume(result => Array.from(result))
  );
}

// ============= EXAMPLES =============

// Example 1: Basic interleaving
console.log("Example 1: Basic interleaving");
const result1 = interleaveBySequence(
  [[1, 2, 3], ['a', 'b', 'c'], [10, 20, 30]],
  [0, 1, 2, 0, 1, 2, 0, 1, 2]
);
console.log(result1);
// Output: [1, 'a', 10, 2, 'b', 20, 3, 'c', 30]

