```javascript
/**
 * Solves two coupled nonlinear equations using Newton's method
 * @param {Function} equations - Function returning [f1(x,y), f2(x,y)]
 * @param {Function} jacobian - Function returning [[df1/dx, df1/dy], [df2/dx, df2/dy]]
 * @param {Array} initialGuess - Starting point [x0, y0]
 * @param {Object} options - Optional configuration
 * @returns {Object} Solution object with roots, iterations, and convergence info
 */
function solveCoupledNonlinear(equations, jacobian, initialGuess, options = {}) {
  // Default options
  const maxIterations = options.maxIterations || 100;
  const tolerance = options.tolerance || 1e-10;
  const verbose = options.verbose || false;

  let x = initialGuess[0];
  let y = initialGuess[1];
  let iteration = 0;
  let converged = false;
  const history = [];

  if (verbose) {
    console.log("Starting Newton's method for coupled nonlinear equations");
    console.log(`Initial guess: [${x}, ${y}]`);
  }

  while (iteration < maxIterations) {
    // Evaluate equations at current point
    const [f1, f2] = equations(x, y);
    const residual = Math.sqrt(f1 * f1 + f2 * f2);

    // Store history
    history.push({ iteration, x, y, f1, f2, residual });

    if (verbose) {
      console.log(
        `Iteration ${iteration}: x=${x.toFixed(8)}, y=${y.toFixed(8)}, residual=${residual.toExponential(3)}`
      );
    }

    // Check convergence
    if (residual < tolerance) {
      converged = true;
      if (verbose) console.log(`Converged in ${iteration} iterations`);
      break;
    }

    // Compute Jacobian matrix
    const J = jacobian(x, y);
    const [[df1dx, df1dy], [df2dx, df2dy]] = J;

    // Compute determinant
    const det = df1dx * df2dy - df1dy * df2dx;

    if (Math.abs(det) < 1e-15) {
      throw new Error(
        `Singular Jacobian at iteration ${iteration}: det = ${det}`
      );
    }

    // Solve J * delta = -F using Cramer's rule
    const deltaX = -(f1 * df2dy - f2 * df1dy) / det;
    const deltaY = -(df1dx * f2 - df2dx * f1) / det;

    // Update solution
    x += deltaX;
    y += deltaY;

    iteration++;
  }

  if (!converged && verbose) {
    console.warn(
      `Did not converge after ${maxIterations} iterations (residual: ${history[history.length - 1].residual})`
    );
  }

  return {
    roots: [x, y],
    x,
    y,
    iterations: iteration,
    converged,
    residual: history[history.length - 1].residual,
    history,
  };
}

