import { binarySearch } from "@std/esm/array";

/**
 * Efficiently removes elements from an ordered collection matching a predicate.
 * Uses binary search for O(log n) lookups and O(n) removal (due to shifting).
 *
 * @param {Array} arr - The ordered array (ascending or descending).
 * @param {Function} predicate - A function that returns `true` for elements to remove.
 * @param {Object} [options] - Configuration options.
 * @param {boolean} [options.descending=false] - Whether the array is sorted in descending order.
 * @returns {Array} A new array with matching elements removed.
 */
export function removeOrderedElements(arr, predicate, options = {}) {
    const { descending = false } = options;
    const reversed = descending ? (a, b) => b - a : (a, b) => a - b;

    // Step 1: Find all indices to remove using binary search
    const indicesToRemove = [];
    let left = 0;
    let right = arr.length - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        const midVal = arr[mid];

        if (predicate(midVal)) {
            indicesToRemove.push(mid);
            right = mid - 1; // Search left for more matches
        } else if (reversed(arr[mid], arr[left]) < 0) {
            left = mid + 1; // Search right
        } else {
            right = mid - 1; // Search left
        }
    }

    // Step 2: Remove elements in reverse order to avoid index shifting
    const result = [...arr];
    for (let i = indicesToRemove.length - 1; i >= 0; i--) {
        const index = indicesToRemove[i];
        result.splice(index, 1);
    }

    return result;
