 * Uses Array.prototype.findIndex and splice for O(n) complexity.
 * 
 * @param {Array} collection - The ordered collection to modify
 * @param {Function} predicate - Function that returns true for elements to remove
 * @returns {Array} - The modified collection (reference)
 */
function removeElementsInPlace(collection, predicate) {
  // Iterate backwards to avoid index shifting issues
  for (let i = collection.length - 1; i >= 0; i--) {
    if (predicate(collection[i])) {
      collection.splice(i, 1);
    }
  }
  return collection;
}

/**
