 * @param {Array} collection - The ordered collection
 * @param {Function} predicate - Function that returns true for elements to remove
 * @returns {Array} - New array with elements removed
 */
function removeElementsImmutable(collection, predicate) {
  let result = collection;

  for (let i = collection.length - 1; i >= 0; i--) {
    if (predicate(collection[i])) {
      result = result.toSpliced(i, 1);
    }
  }

  return result;
