# K-Means Clustering Function

```javascript
/**
 * Partitions a 1D array into k clusters using the k-means algorithm
 * @param {number[]} arr0 - Input array of numbers to cluster
 * @param {number} k - Number of clusters (default: 3)
 * @param {number} maxIterations - Maximum iterations (default: 100)
 * @param {number} tolerance - Convergence tolerance (default: 1e-4)
 * @returns {number[]} Array of cluster labels for each element
 */
function kMeansClustering(arr0, k = 3, maxIterations = 100, tolerance = 1e-4) {
  if (arr0.length === 0) return [];
  if (k <= 0 || k > arr0.length) {
    throw new Error('k must be between 1 and array length');
  }

  // Initialize centroids by randomly selecting k points from the data
  let centroids = [];
  const indices = new Set();
  while (centroids.length < k) {
    const idx = Math.floor(Math.random() * arr0.length);
    if (!indices.has(idx)) {
      indices.add(idx);
      centroids.push(arr0[idx]);
    }
  }

  let labels = new Array(arr0.length).fill(0);
  let prevCentroids = [];

  // Main k-means iteration loop
  for (let iter = 0; iter < maxIterations; iter++) {
    // Assignment step: assign each point to nearest centroid
    labels = arr0.map((value) => {
      let minDist = Infinity;
      let nearestCluster = 0;

      for (let c = 0; c < k; c++) {
        const dist = Math.abs(value - centroids[c]);
        if (dist < minDist) {
          minDist = dist;
          nearestCluster = c;
        }
      }
      return nearestCluster;
    });

    // Update step: recalculate centroids
    prevCentroids = [...centroids];
    centroids = new Array(k).fill(0);
    const counts = new Array(k).fill(0);

    for (let i = 0; i < arr0.length; i++) {
      const cluster = labels[i];
      centroids[cluster] += arr0[i];
      counts[cluster]++;
    }

    for (let c = 0; c < k; c++) {
      if (counts[c] > 0) {
        centroids[c] /= counts[c];
      } else {
        // Handle empty clusters by reinitializing
        const randomIdx = Math.floor(Math.random() * arr0.length);
        centroids[c] = arr0[randomIdx];
      }
    }

    // Check for convergence
    const converged = centroids.every((centroid, i) =>
      Math.abs(centroid - prevCentroids[i]) < tolerance
    );

    if (converged) {
      break;
    }
  }

  return labels;
}

// Example usage:
const data = [1.2, 1.5, 1.8, 8.5, 8.8, 9.2, 5.0, 5.3, 5.5];
const numClusters = 3;

const clusterLabels = kMeansClustering(data, numClusters);
console.log('Input array:', data);
console.log('Cluster labels:', clusterLabels);
console.log('Expected: points 0-2 in cluster 0, 6-8 in cluster 1, 3-5 in cluster 2 (or similar)');

// Another example with different data
