async function encodeCategoriesToIntegers(df0, col0) {
  /**
   * Maps each unique category in a specified column to an integer code
   * and replaces the original column values with numeric codes.
   * 
   * @param {Array<Object>} df0 - Input data table (array of objects)
   * @param {string} col0 - Column name to encode
   * @returns {Promise<Array<Object>>} - Data table with encoded column
   */

  // Initialize DuckDB
  const db = new duckdb.AsyncDatabase();
  const conn = await db.connect();

  try {
    // Register the input data as a table
    await conn.insertArrowFromIPCStream(
      new Uint8Array(
        // Convert data to Arrow format for DuckDB
        JSON.stringify(df0)
      )
    );

    // Create mapping of unique categories to integer codes
    const uniqueQuery = `
      SELECT DISTINCT ${col0} as category,
             ROW_NUMBER() OVER (ORDER BY ${col0}) - 1 as code
      FROM df0
      ORDER BY code
    `;

    const mappingResult = await conn.query(uniqueQuery);
    const categoryMap = new Map();

    // Build category to code mapping
    for await (const row of mappingResult) {
      categoryMap.set(row[col0], row.code);
    }

    // Replace original values with codes
