/**
 * Sorts a 2D data table by multiple specified columns
 * @param {Array<Array>} df0 - 2D array representing the data table
 * @param {Array<string>} columns - Column names/indices to sort by
 * @param {Array<string>} [order=['asc']] - Sort order for each column ('asc' or 'desc')
 * @returns {Array<Array>} - Sorted 2D array
 */
function sortDataFrameByColumns(df0, columns, order = []) {
  if (!df0 || df0.length === 0) {
    return df0;
  }

  // Ensure order array matches columns length
  while (order.length < columns.length) {
    order.push('asc');
  }

  // Create array of objects for easier sorting
  const headers = df0[0];
  const data = df0.slice(1);

  // Convert to objects with column headers
  const objects = data.map(row => {
    const obj = {};
    headers.forEach((header, index) => {
      obj[header] = row[index];
    });
    return obj;
  });

  // Sort using multi-column comparison
  objects.sort((a, b) => {
    for (let i = 0; i < columns.length; i++) {
      const col = columns[i];
      const dir = order[i].toLowerCase() === 'desc' ? -1 : 1;

      const valA = a[col];
      const valB = b[col];

      // Handle null/undefined
      if (valA == null && valB == null) continue;
      if (valA == null) return dir;
      if (valB == null) return -dir;

      // Compare values
      if (valA < valB) return -dir;
      if (valA > valB) return dir;
    }
    return 0;
  });

  // Convert back to 2D array format
  const result = [headers];
  objects.forEach(obj => {
    const row = headers.map(header => obj[header]);
    result.push(row);
  });

  return result;
}

