 */
function imputeColumnMeansNative(data) {
  if (!data || data.length === 0) return data;

  const numCols = data[0].length;
  const numRows = data.length;

  // Calculate column means
  const columnMeans = Array(numCols).fill(0);
  const columnCounts = Array(numCols).fill(0);

  for (let i = 0; i < numRows; i++) {
    for (let j = 0; j < numCols; j++) {
      const value = data[i][j];
      if (value !== null && value !== undefined && !isNaN(value)) {
        columnMeans[j] += value;
        columnCounts[j]++;
      }
    }
  }

  // Divide by count to get actual means
  for (let j = 0; j < numCols; j++) {
    columnMeans[j] = columnCounts[j] > 0 ? columnMeans[j] / columnCounts[j] : 0;
  }

  // Create imputed dataset
  return data.map(row =>
    row.map((value, colIdx) =>
      (value === null || value === undefined || isNaN(value))
        ? columnMeans[colIdx]
        : value
    )
  );
}
```

