    const query = `
      SELECT SUM(${columnName}) as total
      FROM data
      WHERE ${condition}
    `;

    const result = await connection.query(query);
    const rows = result.toArray();

    return rows[0]?.total ?? 0;
  } finally {
    connection.close();
  }
