 */
function groupAndSum(df0, column_name0) {
  // Import Danfo.js (assuming it's available in environment)
  const dfd = require('danfo-js-node'); // or use import in ES6 modules

  // Ensure input is a Danfo dataframe
  const df = df0 instanceof dfd.DataFrame ? df0 : new dfd.DataFrame(df0);

