  const numericCols = df.columns.filter(col => 
    col !== column_name0 && 
    df[col].dtype !== 'string' && 
    df[col].dtype !== 'boolean'
  );

  // Group by the specified column
  const grouped = df.groupby([column_name0]).sum();

  // Reset index to convert the groupBy column back to ordinary column
  const result = grouped.reset_index();

  return result;
}

