/**
 * Removes all columns that contain only zero values from a tabular dataset
 * @param {Array<Object> | string} data - Input data as array of objects or CSV string
 * @returns {Object} Danfo DataFrame with zero-only columns removed
 */
function deleteZeroOnlyColumns(data) {
  // Convert input to Danfo DataFrame
  let df;

  if (typeof data === 'string') {
    // If CSV string input
    df = dfd.read_csv(data);
  } else if (Array.isArray(data)) {
    // If array of objects
    df = new dfd.DataFrame(data);
  } else {
    throw new Error("Input must be array of objects or CSV string");
  }

  // Get all column names
  const columns = df.columns;

  // Identify columns to keep (those with at least one non-zero value)
  const columnsToKeep = [];

  for (const col of columns) {
    const colData = df[col].values;

    // Check if column has at least one non-zero value
    const hasNonZero = colData.some(val => {
      const num = Number(val);
      return num !== 0 && !Number.isNaN(num);
    });

    if (hasNonZero) {
      columnsToKeep.push(col);
    }
  }

  // Select only the columns to keep
  const result = df.select(columnsToKeep);

  return result;
}

