 * @param {number[][] | Array<Array<number|null|undefined>>} data - 2D numeric dataset
 * @returns {number[][]} - Dataset with missing values replaced
 */
function imputeMissingWithColumnAverage(data) {
  if (!data || data.length === 0) return data;

  const numRows = data.length;
  const numCols = data[0].length;

  // Step 1: Calculate column averages (ignoring null/undefined values)
  const columnAverages = Array(numCols).fill(0);
  const columnCounts = Array(numCols).fill(0);

  for (let i = 0; i < numRows; i++) {
    for (let j = 0; j < numCols; j++) {
      const value = data[i][j];
      if (value !== null && value !== undefined && !isNaN(value)) {
        columnAverages[j] += value;
        columnCounts[j]++;
      }
    }
  }

  // Compute means
  for (let j = 0; j < numCols; j++) {
    columnAverages[j] = columnCounts[j] > 0 ? columnAverages[j] / columnCounts[j] : 0;
  }

  // Step 2: Replace missing values with column averages
  const imputedData = data.map(row => [...row]);

  for (let i = 0; i < numRows; i++) {
    for (let j = 0; j < numCols; j++) {
      if (imputedData[i][j] === null || imputedData[i][j] === undefined || isNaN(imputedData[i][j])) {
        imputedData[i][j] = columnAverages[j];
      }
    }
  }

  return imputedData;
