/**
 * Compute the moving average of a numeric sequence
 * @param {number[]} lst0 - The input numeric sequence
 * @param {number} window_size - The size of the moving average window
 * @returns {number[]} - Array of moving averages
 */
function computeMovingAverage(lst0, window_size) {
  if (!Array.isArray(lst0) || lst0.length === 0) {
    throw new Error("Input must be a non-empty array");
  }

  if (window_size < 1 || window_size > lst0.length) {
    throw new Error("Window size must be between 1 and array length");
  }

  const result = [];

  for (let i = 0; i <= lst0.length - window_size; i++) {
    const window = lst0.slice(i, i + window_size);
    const average = window.reduce((sum, val) => sum + val, 0) / window_size;
    result.push(average);
  }

  return result;
}

// Example usage:
const sequence = [10, 20, 30, 40, 50, 60, 70];
const windowSize = 3;

const movingAverages = computeMovingAverage(sequence, windowSize);
