      hierarchicalIndex.push([key, idx]);
    });

    groupedData.values.forEach((row) => {
      newData.push(row);
    });
  });

  // Create new DataFrame with multi-level index
  const resultDf = new dfd.DataFrame(newData, {
    columns: df0.columns,
    index: hierarchicalIndex
  });

