```javascript
import * as dfd from "danfo-js-node"; // Danfo.js - v2.0+ (2024/2025+)

/**
 * Adds a new column to a dataframe by splitting values from an existing column
 * @param {dfd.DataFrame} df0 - The input dataframe
 * @param {string} sourceColumn - The column to split from (var0)
 * @param {string} targetColumn - The new column name (var1)
 * @param {string|RegExp} delimiter - The delimiter to split by (default: comma)
 * @param {number} index - Which part to extract after split (default: 0 for first part)
 * @returns {dfd.DataFrame} - The dataframe with the new column added
 */
function addSplitColumn(
  df0,
  sourceColumn = "var0",
  targetColumn = "var1",
  delimiter = ",",
  index = 0
) {
  // Extract the source column as an array
  const sourceData = df0[sourceColumn].values;

  // Split each value and extract the specified part
  const splitData = sourceData.map((value) => {
    if (value === null || value === undefined) return null;
    const parts = String(value).split(delimiter);
    return parts[index] ? parts[index].trim() : null;
  });

  // Add the new column to the dataframe
  df0.addColumn({
    column: targetColumn,
    value: splitData,
  });

  return df0;
}

// Example usage:
async function main() {
  // Create sample dataframe
  const df0 = new dfd.DataFrame({
    var0: ["apple,fruit", "carrot,vegetable", "salmon,fish", "lettuce,vegetable"],
    id: [1, 2, 3, 4],
  });

  console.log("Original DataFrame:");
  df0.print();

