        `but ${mapping.length} names provided`
      );
    }

    // Create mapping object from current columns to new names
    const columnMapping = {};
    currentColumns.forEach((col, index) => {
      columnMapping[col] = mapping[index];
    });

    return df0.rename(columnMapping);
  } 
