import * as duckdb from '@duckdb/wasm';

/**
 * Sums values of columns with identical headers in a tabular dataset.
 * Returns a new dataset where each header appears only once with summed values.
 * 
 * @param {Array<Object>} dataset - Array of objects representing table rows
 * @returns {Array<Object>} - Array with summed columns for duplicate headers
 */
async function sumDuplicateColumns(dataset) {
  // Initialize DuckDB
  const db = new duckdb.Database();
  const conn = await db.connect();

  if (!dataset || dataset.length === 0) {
    return [];
  }

  // Get all headers and identify duplicates
  const allHeaders = Object.keys(dataset[0]);
  const headerCounts = {};
  const duplicateHeaders = new Set();

  allHeaders.forEach(header => {
    headerCounts[header] = (headerCounts[header] || 0) + 1;
    if (headerCounts[header] > 1) {
      duplicateHeaders.add(header);
    }
  });

  // Register the dataset as a table
  await conn.insertArrowTable(
    convertToArrowTable(dataset),
    { name: 'source_table' }
  );

  // Build dynamic SQL for summing duplicate columns
  const selectClauses = [];
  const seenHeaders = new Set();

  allHeaders.forEach(header => {
    if (seenHeaders.has(header)) {
      return; // Skip duplicates in select (they're summed)
    }
    seenHeaders.add(header);

    if (duplicateHeaders.has(header)) {
      // Sum all columns with this header
      const columnIndices = allHeaders
        .map((h, i) => h === header ? i : -1)
        .filter(i => i !== -1)
        .map(i => `"${allHeaders[i]}"`)
        .join(' + ');

      selectClauses.push(`(${columnIndices}) AS "${header}"`);
    } else {
      selectClauses.push(`"${header}"`);
    }
  });

  const query = `SELECT ${selectClauses.join(', ')} FROM source_table`;

  // Execute query and fetch results
  const result = await conn.query(query);
  const output = result.toArray();

  await conn.close();

  return output;
}

/**
 * Helper function to convert JavaScript array to Arrow Table format
 */
function convertToArrowTable(dataset) {
  if (dataset.length === 0) return null;

  const headers = Object.keys(dataset[0]);
  const columns = {};

  headers.forEach(header => {
    columns[header] = dataset.map(row => row[header] ?? null);
  });

  return columns;
}

// Example usage:
const testData = [
  { name: 'Alice', score: 10, score: 5, value: 100 },
  { name: 'Bob', score: 20, score: 15, value: 200 },
  { name: 'Charlie', score: 30, score: 25, value: 300 }
];

// Note: JavaScript objects can't actually have duplicate keys,
// so here's a more realistic example:
