  // Convert to Polars DataFrame
  const df = pl.DataFrame(dataset);

  // Get column names and group by name
  const columns = df.columns;
  const columnGroups = {};

  columns.forEach(col => {
    columnGroups[col] = columnGroups[col] ? columnGroups[col] + 1 : 1;
  });

  // Sum duplicate columns
  let result = df;
  const processed = new Set();

  columns.forEach(col => {
    if (!processed.has(col) && columnGroups[col] > 1) {
      // Sum all columns with same name
      const duplicateCols = columns.filter(c => c === col);
      const summed = result.select(duplicateCols).sum(axis=1);
      result = result.drop(col).with_columns(summed.alias(col));
      processed.add(col);
    }
  });

  return result.toRecords();
}

