 * @param {string} var1 - Regular expression pattern to match
 * @returns {Promise<Array>} Filtered dataset as array of objects
 */
async function filterByRegex(df0, var0, var1) {
  // Initialize DuckDB
  const db = new duckdb.Database();
  const connection = await db.connect();

  try {
    // Register the input data
    await connection.insertArrowFromIPCStream(
      new ReadableStream({
        start(controller) {
          // Convert input data to Arrow format
          const arrow = require('apache-arrow');
          const table = arrow.tableFromJSON(df0);
          const writer = new arrow.RecordBatchStreamWriter(table.schema);

          table.batches.forEach(batch => {
