          });
          controller.enqueue(writer.finish());
          controller.close();
        }
      })
    );

    // Execute regex filter query using DuckDB SQL
    const regexPattern = var1.replace(/'/g, "''"); // Escape single quotes
    const query = `
      SELECT * FROM df0 
      WHERE regexp_matches(CAST(${var0} AS VARCHAR), '${regexPattern}')
    `;

    const result = await connection.query(query);
    const filtered = result.toArray();

    return filtered;

  } finally {
