/**
 * Generate every unique subset of a given list that has a specified number of elements,
 * compute the product of the values in each subset, and return the sum of all those products.
 * 
 * @param {number[]} list - The input array of numbers
 * @param {number} k - The number of elements in each subset
 * @returns {number} The sum of products of all k-element subsets
 */
function sumOfSubsetProducts(list, k) {
  // Validate input
  if (!Array.isArray(list) || list.length === 0) {
    throw new Error('Input list must be a non-empty array');
  }

  if (k < 0 || k > list.length || !Number.isInteger(k)) {
    throw new Error('k must be a non-negative integer not exceeding the list length');
  }

  if (k === 0) {
    return 1; // Empty subset has product of 1
