    ? sortBy.split(':')
    : [sortBy, 'desc'];

  const direction = order === 'asc' ? 1 : -1;

  if (field === 'count') {
    return results.sort((a, b) => (a.count - b.count) * direction);
  } else if (field === 'tuple') {
    return results.sort((a, b) => 
      JSON.stringify(a.tuple).localeCompare(JSON.stringify(b.tuple)) * direction
    );
  }

  return results;
}

